+			sys_drv_cpu_clk_div_get(2), sys_hal_vdddig_h_vol_get(), required);
+		return BK_FAIL;
+	}
+#if CONFIG_RX_OPTIMIZE
+	if (sys_hal_vddd_h_vol_get() < 0x7)
+	{
